mapper.update:
UPDATE t_record
amount = #{amount}, type = #{type}, category = #{category}, remark = #{remark}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM t_record
WHERE user_id = #{userId}
AND type = #{type}
AND category = #{category}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC

SELECT IFNULL(SUM(amount), 0) FROM t_record
WHERE user_id = #{userId} AND type = #{type}
AND create_time >= #{startTime}
AND create_time <= #{endTime}

SELECT category, SUM(amount) as total, COUNT(*) as count
FROM t_record
WHERE user_id = #{userId} AND type = #{type}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY category
ORDER BY total DESC

SELECT DATE_FORMAT(create_time, '%Y-%m') as month,
       SUM(CASE WHEN type = '收入' THEN amount ELSE 0 END) as income,
       SUM(CASE WHEN type = '支出' THEN amount ELSE 0 END) as expense
FROM t_record
WHERE user_id = #{userId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m')
ORDER BY month
